import{_ as e,g as a,e as s,a4 as d}from"./chunks/framework.CEYJDsBW.js";const h=JSON.parse('{"title":"在正文预览 NBT 与 SNBT","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/26.1/packs/structures.md","filePath":"ageratum/26.1/packs/structures.md"}'),n={name:"ageratum/26.1/packs/structures.md"};function o(c,t,r,p,i,l){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="在正文预览-nbt-与-snbt" tabindex="-1">在正文预览 NBT 与 SNBT <a class="header-anchor" href="#在正文预览-nbt-与-snbt" aria-label="Permalink to &quot;在正文预览 NBT 与 SNBT&quot;">​</a></h1><p>在 <code>assets/workshop/ageratum/zh_cn/maintenance/</code> 并排创建 <code>repair.md</code>、<code>stand.snbt</code>。页面只需引用同目录文件。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 展示台底座</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;structure id=&quot;stand.snbt&quot;/&gt;</span></span></code></pre></div><p><code>stand.snbt</code> 可以用一个完整的单方块结构开始。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  DataVersion: 4790,</span></span>
<span class="line"><span>  size: [1, 1, 1],</span></span>
<span class="line"><span>  palette: [{Name: &quot;minecraft:anvil&quot;}],</span></span>
<span class="line"><span>  blocks: [{pos: [0, 0, 0], state: 0}],</span></span>
<span class="line"><span>  entities: []</span></span>
<span class="line"><span>}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>用途</th></tr></thead><tbody><tr><td>标签属性 <code>id</code>、<code>path</code></td><td>路径字符串</td><td>至少填一个，<code>id</code> 优先。相对路径从当前 Markdown 所在目录解析。</td></tr><tr><td><code>size</code></td><td>三个整数的列表</td><td>结构在 X、Y、Z 的尺寸，按这个顺序记录。</td></tr><tr><td><code>palette</code> 或 <code>palettes</code></td><td>方块状态列表或多套列表</td><td>至少提供一套调色板。状态用 <code>Name</code> 和可选的 <code>Properties</code> 字符串映射。</td></tr><tr><td><code>blocks</code></td><td>compound 列表</td><td>每项用三整数 <code>pos</code> 和调色板索引 <code>state</code>。方块实体信息可放在该项的 <code>nbt</code>。</td></tr><tr><td><code>entities</code></td><td>compound 列表</td><td>可选。本例没有实体，显式写空列表。</td></tr><tr><td><code>DataVersion</code></td><td>整数</td><td>记录结构的数据版本。建议保留游戏导出的值。</td></tr></tbody></table><p>带命名空间时使用资源管理器中的全路径，例如 <code>workshop:ageratum/zh_cn/maintenance/stand.snbt</code>。扩展名缺省时先试原路径，再试 <code>.nbt</code>、<code>.snbt</code>。组件用 gzip 文件头识别压缩 NBT，否则先尝试文本 SNBT，再尝试另一种解码方式。文本上限为 8 MiB。只为文档预览时，SNBT 便于版本控制和人工审查。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">预览读取与格式转换</a></p><p>客户端找不到直接资源时，还会用模组 classloader 查询 <code>data/&lt;命名空间&gt;/structure/</code> 与 <code>structures/</code> 下的内置 NBT、SNBT。这条回退只看 classpath。分发独立预览请使用 <code>assets</code>，随世界启用的服务端数据包不会进入该客户端 classloader。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDNBTStructureComponent.java" target="_blank" rel="noreferrer">路径解析</a></p>`,8)])])}const b=e(n,[["render",o]]);export{h as __pageData,b as default};
